// Filter findings to critical/high only
const input = $input.first().json;
const findings = (input.body?.findings || []).filter(
  f => f.severity === 'critical' || f.severity === 'high'
);

if (findings.length === 0) {
  return [{ json: { skipped: true, message: 'No critical/high findings to create issues for' } }];
}

return findings.map(f => ({
  json: {
    ...f,
    repoOwner: input.body?.repoOwner,
    repoName: input.body?.repoName,
    scanId: input.body?.scanId
  }
}));

const finding = $input.first().json;

if (finding.skipped) {
  return [{ json: finding }];
}

const severityEmoji = finding.severity === 'critical' ? '🔴' : '🟠';
const labels = ['security', `severity:${finding.severity}`, 'codehardener'];

const title = `${severityEmoji} [${finding.severity.toUpperCase()}] ${finding.title}`;
const body = [
  `## Security Finding`,
  ``,
  `**Severity:** ${finding.severity}`,
  `**Scanner:** ${finding.scanner || 'unknown'}`,
  `**Rule:** ${finding.ruleId || 'N/A'}`,
  finding.filePath ? `**File:** \`${finding.filePath}${finding.lineNumber ? `:${finding.lineNumber}` : ''}\`` : '',
  finding.cweId ? `**CWE:** ${finding.cweId}` : '',
  ``,
  `### Description`,
  finding.description || 'No description available.',
  ``,
  finding.fixDescription ? `### Recommended Fix\n${finding.fixDescription}` : '',
  ``,
  `---`,
  `*Created by Code Hardener scan \`${finding.scanId}\`*`
].filter(Boolean).join('\n');

return [{ json: { title, body, labels, repoOwner: finding.repoOwner, repoName: finding.repoName } }];

// Create GitHub issue (requires GitHub credentials configured in n8n)
const issue = $input.first().json;

if (issue.skipped) {
  return [{ json: issue }];
}

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.github.com/repos/${issue.repoOwner}/${issue.repoName}/issues`,
    headers: {
      'Authorization': `token ${process.env.GITHUB_TOKEN}`,
      'Accept': 'application/vnd.github.v3+json',
      'Content-Type': 'application/json'
    },
    body: {
      title: issue.title,
      body: issue.body,
      labels: issue.labels
    }
  });

  return [{ json: { created: true, issueUrl: response.html_url, issueNumber: response.number } }];
} catch (error) {
  return [{ json: { created: false, error: error.message } }];
}

const results = $input.all().map(item => item.json);
const created = results.filter(r => r.created).length;

return [{ json: { total: results.length, created, results } }];
